// Resolve current DNS records for each monitored domain directly via Node's
// built-in dns module - no external API call is made. Also probes DNSSEC
// signing status by checking for the presence of RRSIG-adjacent DS/DNSKEY-
// era resolution success as a lightweight proxy (full RRSIG validation
// would require a validating resolver; this flags obvious loss of signing).
const dns = require('dns').promises;
const config = $input.item.json;
const domains = config.domains || [];

async function safeResolve(domain, type) {
  try {
    if (type === 'A') return await dns.resolve4(domain);
    if (type === 'AAAA') return await dns.resolve6(domain);
    if (type === 'MX') return (await dns.resolveMx(domain)).map(m => `${m.priority} ${m.exchange}`);
    if (type === 'NS') return await dns.resolveNs(domain);
    if (type === 'TXT') return (await dns.resolveTxt(domain)).map(t => t.join(''));
    if (type === 'CNAME') return await dns.resolveCname(domain);
    if (type === 'SOA') { const s = await dns.resolveSoa(domain); return [`${s.nsname} serial=${s.serial}`]; }
    return [];
  } catch (err) {
    return [];
  }
}

async function checkDnssec(domain) {
  try {
    const records = await dns.resolveAny(domain);
    const hasSigningIndicator = records.some(r => r.type === 'DS' || r.type === 'DNSKEY' || r.type === 'RRSIG');
    return { checked: true, dnssecDetected: hasSigningIndicator };
  } catch (err) {
    return { checked: false, dnssecDetected: false };
  }
}

const results = [];
for (const domainConfig of domains) {
  const domain = domainConfig.domain;
  const [a, aaaa, mx, ns, txt, cname, soa, dnssec] = await Promise.all([
    safeResolve(domain, 'A'),
    safeResolve(domain, 'AAAA'),
    safeResolve(domain, 'MX'),
    safeResolve(domain, 'NS'),
    safeResolve(domain, 'TXT'),
    safeResolve(domain, 'CNAME'),
    safeResolve(domain, 'SOA'),
    checkDnssec(domain)
  ]);

  results.push({
    json: {
      ...config,
      domain,
      requireDnssec: !!domainConfig.requireDnssec,
      expectedRecords: domainConfig.expectedRecords || {},
      currentRecords: { A: a, AAAA: aaaa, MX: mx, NS: ns, TXT: txt, CNAME: cname, SOA: soa },
      dnssecDetected: dnssec.dnssecDetected,
      dnssecCheckSucceeded: dnssec.checked,
      resolvedAt: new Date().toISOString()
    }
  });
}

return results;

// Parse the RDAP response for a registry expiration event. RDAP is a free,
// keyless, standardized successor to WHOIS - no credential needed. Fails
// open (treats expiry as unknown, not critical) if RDAP is unavailable or
// the response shape is unexpected, so a lookup outage never becomes a
// false Critical alert on its own.
const item = $input.item.json;
const body = item.body || item;

let expirationDate = null;
try {
  const events = body.events || [];
  const expEvent = events.find(e => e.eventAction === 'expiration');
  if (expEvent && expEvent.eventDate) expirationDate = expEvent.eventDate;
} catch (e) {
  expirationDate = null;
}

let daysUntilExpiry = null;
if (expirationDate) {
  const msPerDay = 1000 * 60 * 60 * 24;
  daysUntilExpiry = Math.ceil((new Date(expirationDate).getTime() - Date.now()) / msPerDay);
}

const expiryLookupSucceeded = expirationDate !== null;

return {
  json: {
    ...item,
    expirationDate,
    daysUntilExpiry,
    expiryLookupSucceeded
  }
};

// Diff the freshly resolved DNS records against the expected baseline per
// record type, layer in expiry risk and DNSSEC posture, compute a single
// weighted drift score, and append this cycle's diff to a rolling per-
// domain change history using workflow static data (persists across runs,
// no external DB needed).
const item = $input.item.json;
const expected = item.expectedRecords || {};
const current = item.currentRecords || {};

function diffArrays(expectedArr, currentArr) {
  const exp = (expectedArr || []).map(String);
  const cur = (currentArr || []).map(String);
  const added = cur.filter(v => !exp.includes(v));
  const removed = exp.filter(v => !cur.includes(v));
  return { added, removed, changed: added.length > 0 || removed.length > 0 };
}

const recordTypes = ['A', 'AAAA', 'MX', 'NS', 'TXT', 'CNAME', 'SOA'];
const diffs = {};
const changedRecordTypes = [];

for (const type of recordTypes) {
  const d = diffArrays(expected[type], current[type]);
  diffs[type] = d;
  if (d.changed) changedRecordTypes.push(type);
}

const nsChanged = diffs.NS.changed;
const mxChanged = diffs.MX.changed;
const aOrAaaaChanged = diffs.A.changed || diffs.AAAA.changed;
const txtChanged = diffs.TXT.changed;

const allowedIpRanges = item.allowedIpCidrPrefixes || [];
const suspiciousIpAdded = diffs.A.added.some(ip => allowedIpRanges.length > 0 && !allowedIpRanges.some(prefix => ip.startsWith(prefix)));

const changesDetected = changedRecordTypes.length > 0;

// --- DNSSEC posture ---
const dnssecDropped = item.requireDnssec && item.dnssecCheckSucceeded && !item.dnssecDetected;

// --- Expiry risk ---
const warnDays = item.domainExpiryWarningDays ?? 30;
const critDays = item.domainExpiryCriticalDays ?? 7;
let expiryRisk = 'None';
if (item.expiryLookupSucceeded && typeof item.daysUntilExpiry === 'number') {
  if (item.daysUntilExpiry <= critDays) expiryRisk = 'Critical';
  else if (item.daysUntilExpiry <= warnDays) expiryRisk = 'Warning';
}

// --- Weighted drift score (0-100) ---
let driftScore = 0;
if (nsChanged) driftScore += 40;
if (suspiciousIpAdded) driftScore += 35;
if (mxChanged) driftScore += 20;
if (txtChanged) driftScore += 10;
if (aOrAaaaChanged && !suspiciousIpAdded) driftScore += 10;
if (diffs.CNAME.changed) driftScore += 10;
if (dnssecDropped) driftScore += 25;
if (expiryRisk === 'Critical') driftScore += 30;
else if (expiryRisk === 'Warning') driftScore += 10;
driftScore = Math.min(100, driftScore);

// --- Rolling change history via workflow static data, keyed per domain ---
const staticData = $getWorkflowStaticData('node');
if (!staticData.historyByDomain) staticData.historyByDomain = {};
if (!staticData.historyByDomain[item.domain]) staticData.historyByDomain[item.domain] = [];

const historyEntry = {
  timestamp: item.resolvedAt,
  changedRecordTypes,
  driftScore,
  dnssecDropped,
  expiryRisk
};
staticData.historyByDomain[item.domain].push(historyEntry);
if (staticData.historyByDomain[item.domain].length > 30) staticData.historyByDomain[item.domain].shift();

const recentHistory = staticData.historyByDomain[item.domain];
const changeFrequencyLast30Cycles = recentHistory.filter(h => h.changedRecordTypes.length > 0).length;
const repeatedProbingSuspected = changeFrequencyLast30Cycles >= 3 && changesDetected;

return {
  json: {
    ...item,
    diffs,
    changedRecordTypes,
    changesDetected,
    nsChanged,
    mxChanged,
    aOrAaaaChanged,
    txtChanged,
    suspiciousIpAdded,
    dnssecDropped,
    expiryRisk,
    driftScore,
    changeFrequencyLast30Cycles,
    repeatedProbingSuspected,
    recentHistory: recentHistory.slice(-5)
  }
};

// Turn the drift score and diff into a threat severity, a security-team
// facing alert, and - for confirmed-stable, low-risk changes - a proposed
// baseline update for human sign-off, so the same accepted change doesn't
// re-alert every cycle.
const item = $input.item.json;

let severity = 'Info';
let primaryConcern = 'Minor DNS record change';

if (item.nsChanged || item.suspiciousIpAdded || item.expiryRisk === 'Critical' || item.dnssecDropped) {
  severity = 'Critical';
  if (item.nsChanged) primaryConcern = 'Nameserver change detected - possible domain hijack or unauthorized registrar transfer';
  else if (item.suspiciousIpAdded) primaryConcern = 'A/AAAA record now points to an IP outside the approved range - possible traffic redirection';
  else if (item.expiryRisk === 'Critical') primaryConcern = `Domain expires in ${item.daysUntilExpiry} day(s) - immediate renewal required to avoid an outage`;
  else if (item.dnssecDropped) primaryConcern = 'DNSSEC signing appears to have been dropped since baseline - zone may be vulnerable to spoofing';
} else if (item.mxChanged || item.aOrAaaaChanged || item.expiryRisk === 'Warning' || item.repeatedProbingSuspected) {
  severity = 'Warning';
  if (item.mxChanged) primaryConcern = 'Mail exchange (MX) record changed - possible email interception/spoofing setup';
  else if (item.aOrAaaaChanged) primaryConcern = 'A/AAAA record changed - verify the new target is expected';
  else if (item.expiryRisk === 'Warning') primaryConcern = `Domain expires in ${item.daysUntilExpiry} day(s) - schedule renewal`;
  else if (item.repeatedProbingSuspected) primaryConcern = `Domain has changed in ${item.changeFrequencyLast30Cycles} of the last 30 scan cycles - possible reconnaissance/probing pattern`;
} else if (item.txtChanged) {
  severity = 'Warning';
  primaryConcern = 'TXT record changed - review SPF/DKIM/DMARC entries for tampering';
}

const alertTitle = `${severity} DNS/domain risk (drift score ${item.driftScore}/100): ${item.domain}`;
const alertDescription = `Domain ${item.domain} changed record type(s): ${item.changedRecordTypes.join(', ') || 'none'}. `
  + `Expiry risk: ${item.expiryRisk}${item.daysUntilExpiry != null ? ` (${item.daysUntilExpiry} days remaining)` : ' (lookup unavailable)'}. `
  + `DNSSEC dropped: ${item.dnssecDropped}. `
  + `${item.primaryConcern || primaryConcern}. Resolved at ${item.resolvedAt}.`;

const recommendedAction = severity === 'Critical'
  ? 'Immediately verify registrar/DNS provider account activity and domain renewal status; confirm the change was authorized and lock the domain if not.'
  : severity === 'Warning'
    ? 'Confirm the change with the owning team, and either renew the domain or update the expected-records baseline if legitimate.'
    : 'Log for awareness; update the baseline if the change is expected.';

// Propose a baseline update only for genuinely low-risk, non-security-sensitive
// drift (Info-level record changes with no expiry/DNSSEC concern) - never for
// NS, suspicious IP, expiry, or DNSSEC findings, which always require a human
// to confirm authorization first.
const safeRecordTypesOnly = item.changedRecordTypes.every(t => ['TXT', 'CNAME', 'SOA'].includes(t));
const proposeBaselineUpdate = severity === 'Info' && item.changesDetected && safeRecordTypesOnly && !item.dnssecDropped && item.expiryRisk === 'None';

return {
  json: {
    ...item,
    severity,
    primaryConcern,
    alertTitle,
    alertDescription,
    recommendedAction,
    proposeBaselineUpdate,
    proposedBaselineRecords: proposeBaselineUpdate ? item.currentRecords : null
  }
};
